// src/lib.rs
use parking_lot::RwLock;
use std::collections::{HashMap, VecDeque};
use std::sync::Arc;
use std::time::{SystemTime, UNIX_EPOCH, Duration};
use tokio::task::JoinHandle;

#[derive(Clone, Debug)]
pub struct CacheEntry<V: Clone> {
    pub value: V,
    pub expires_at: u64,
    pub size: usize,
    pub last_accessed: u64,
    pub access_count: u64,
}

#[derive(Clone, Debug)]
pub struct EvictionReason {
    pub reason: String, // "expired", "lru", "memory"
}

pub type OnEvictFn = Arc<dyn Fn(String, String) + Send + Sync>;

pub struct CacheConfig {
    pub max_entries: usize,
    pub default_ttl_ms: u64,
    pub max_memory_bytes: usize,
    pub eviction_check_interval_ms: u64,
    pub on_evict: Option<OnEvictFn>,
}

impl Default for CacheConfig {
    fn default() -> Self {
        Self {
            max_entries: 1000,
            default_ttl_ms: 60000,
            max_memory_bytes: 100 * 1024 * 1024,
            eviction_check_interval_ms: 5000,
            on_evict: None,
        }
    }
}

#[derive(Clone, Debug)]
pub struct CacheStats {
    pub hits: u64,
    pub misses: u64,
    pub evictions: u64,
    pub expirations: u64,
    pub size: usize,
    pub memory: usize,
}

struct CacheInner<V: Clone> {
    entries: HashMap<String, CacheEntry<V>>,
    access_order: VecDeque<String>,
    current_memory: usize,
    stats: CacheStats,
}

pub struct LRUCache<V: Clone> {
    config: CacheConfig,
    inner: Arc<RwLock<CacheInner<V>>>,
    eviction_task: Arc<RwLock<Option<JoinHandle<()>>>>,
}

impl<V: Clone + Send + Sync + 'static> LRUCache<V> {
    pub fn new(config: CacheConfig) -> Self {
        Self {
            config,
            inner: Arc::new(RwLock::new(CacheInner {
                entries: HashMap::new(),
                access_order: VecDeque::new(),
                current_memory: 0,
                stats: CacheStats {
                    hits: 0,
                    misses: 0,
                    evictions: 0,
                    expirations: 0,
                    size: 0,
                    memory: 0,
                },
            })),
            eviction_task: Arc::new(RwLock::new(None)),
        }
    }

    pub fn get(&self, key: &str) -> Option<V> {
        let mut inner = self.inner.write();

        let entry = inner.entries.get(key)?;
        let now = current_time_ms();

        if now > entry.expires_at {
            let entry = inner.entries.remove(key).unwrap();
            inner.access_order.retain(|k| k != key);
            inner.current_memory -= entry.size;
            inner.stats.expirations += 1;
            inner.stats.misses += 1;

            if let Some(on_evict) = &self.config.on_evict {
                on_evict(key.to_string(), "expired".to_string());
            }

            return None;
        }

        let mut entry = entry.clone();
        entry.last_accessed = now;
        entry.access_count += 1;
        inner.entries.insert(key.to_string(), entry.clone());

        Self::move_to_front(&mut inner.access_order, key);

        inner.stats.hits += 1;
        Some(entry.value)
    }

    pub fn put(&self, key: &str, value: V, ttl_ms: Option<u64>, size: Option<usize>) {
        let mut inner = self.inner.write();

        let size = size.unwrap_or_else(|| Self::estimate_size(&value));
        let ttl = ttl_ms.unwrap_or(self.config.default_ttl_ms);
        let now = current_time_ms();

        if let Some(old_entry) = inner.entries.remove(key) {
            inner.current_memory -= old_entry.size;
            inner.access_order.retain(|k| k != key);
        }

        while inner.current_memory + size > self.config.max_memory_bytes && !inner.access_order.is_empty() {
            Self::evict_lru(&mut inner, self.config.on_evict.as_ref(), "memory");
        }

        while inner.entries.len() >= self.config.max_entries && !inner.access_order.is_empty() {
            Self::evict_lru(&mut inner, self.config.on_evict.as_ref(), "lru");
        }

        let entry = CacheEntry {
            value,
            expires_at: now + ttl,
            size,
            last_accessed: now,
            access_count: 0,
        };

        inner.current_memory += size;
        inner.entries.insert(key.to_string(), entry);
        Self::move_to_front(&mut inner.access_order, key);
    }

    pub fn delete(&self, key: &str, reason: &str) -> bool {
        let mut inner = self.inner.write();

        match inner.entries.remove(key) {
            Some(entry) => {
                inner.current_memory -= entry.size;
                inner.access_order.retain(|k| k != key);

                match reason {
                    "expired" => inner.stats.expirations += 1,
                    _ => inner.stats.evictions += 1,
                }

                if let Some(on_evict) = &self.config.on_evict {
                    on_evict(key.to_string(), reason.to_string());
                }

                true
            }
            None => false,
        }
    }

    pub fn has(&self, key: &str) -> bool {
        let inner = self.inner.read();

        match inner.entries.get(key) {
            Some(entry) => {
                let now = current_time_ms();
                now <= entry.expires_at
            }
            None => false,
        }
    }

    pub fn size(&self) -> usize {
        self.inner.read().entries.len()
    }

    pub fn memory_usage(&self) -> usize {
        self.inner.read().current_memory
    }

    pub fn get_stats(&self) -> CacheStats {
        let inner = self.inner.read();
        CacheStats {
            hits: inner.stats.hits,
            misses: inner.stats.misses,
            evictions: inner.stats.evictions,
            expirations: inner.stats.expirations,
            size: inner.entries.len(),
            memory: inner.current_memory,
        }
    }

    pub fn clear(&self) {
        let mut inner = self.inner.write();
        let keys: Vec<_> = inner.entries.keys().cloned().collect();

        for key in keys {
            if let Some(entry) = inner.entries.remove(&key) {
                inner.current_memory -= entry.size;
                inner.stats.evictions += 1;
            }
        }

        inner.access_order.clear();

        if let Some(on_evict) = &self.config.on_evict {
            for key in inner.entries.keys() {
                on_evict(key.clone(), "lru".to_string());
            }
        }
    }

    pub async fn start_eviction_loop(&self) {
        let mut task_guard = self.eviction_task.write();

        if task_guard.is_some() {
            return;
        }

        let inner_clone = Arc::clone(&self.inner);
        let config_on_evict = self.config.on_evict.clone();
        let interval_ms = self.config.eviction_check_interval_ms;

        let task = tokio::spawn(async move {
            loop {
                tokio::time::sleep(Duration::from_millis(interval_ms)).await;

                let mut inner = inner_clone.write();
                let now = current_time_ms();

                let expired_keys: Vec<_> = inner
                    .entries
                    .iter()
                    .filter(|(_, entry)| now > entry.expires_at)
                    .map(|(key, _)| key.clone())
                    .collect();

                for key in expired_keys {
                    if let Some(entry) = inner.entries.remove(&key) {
                        inner.current_memory -= entry.size;
                        inner.stats.expirations += 1;

                        if let Some(on_evict) = &config_on_evict {
                            on_evict(key, "expired".to_string());
                        }
                    }
                }
            }
        });

        *task_guard = Some(task);
    }

    pub async fn stop_eviction_loop(&self) {
        let mut task_guard = self.eviction_task.write();

        if let Some(task) = task_guard.take() {
            task.abort();
        }
    }

    pub fn keys(&self) -> Vec<String> {
        self.inner
            .read()
            .access_order
            .iter()
            .cloned()
            .collect()
    }

    pub fn values(&self) -> Vec<V> {
        let inner = self.inner.read();
        inner
            .access_order
            .iter()
            .filter_map(|key| inner.entries.get(key).map(|e| e.value.clone()))
            .collect()
    }

    fn move_to_front(access_order: &mut VecDeque<String>, key: &str) {
        access_order.retain(|k| k != key);
        access_order.push_front(key.to_string());
    }

    fn evict_lru(
        inner: &mut CacheInner<V>,
        on_evict: Option<&OnEvictFn>,
        reason: &str,
    ) {
        if let Some(oldest) = inner.access_order.pop_back() {
            if let Some(entry) = inner.entries.remove(&oldest) {
                inner.current_memory -= entry.size;

                match reason {
                    "expired" => inner.stats.expirations += 1,
                    _ => inner.stats.evictions += 1,
                }

                if let Some(on_evict_fn) = on_evict {
                    on_evict_fn(oldest, reason.to_string());
                }
            }
        }
    }

    fn estimate_size(value: &V) -> usize {
        // For String type, use len * 2 as approximation
        // For generic types, return a default estimate
        std::mem::size_of_val(value).max(64)
    }
}

fn current_time_ms() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_millis() as u64
}

