mod tests {
    use super::*;
    use std::sync::atomic::{AtomicUsize, Ordering};

    #[test]
    fn test_basic_get_put() {
        let cache = LRUCache::new(CacheConfig {
            max_entries: 3,
            default_ttl_ms: 100,
            ..Default::default()
        });

        cache.put("a", "hello", None, None);
        assert_eq!(cache.get("a"), Some("hello"));
        assert_eq!(cache.size(), 1);
    }

    #[test]
    fn test_lru_eviction() {
        let cache = LRUCache::new(CacheConfig {
            max_entries: 3,
            default_ttl_ms: 100,
            ..Default::default()
        });

        cache.put("a", "hello", None, None);
        cache.put("b", "world", None, None);
        cache.put("c", "foo", None, None);
        cache.put("d", "bar", None, None); // should evict 'a'

        assert!(!cache.has("a"));
        assert!(cache.has("d"));
    }

    #[tokio::test]
    async fn test_ttl_expiration() {
        let cache = LRUCache::new(CacheConfig {
            max_entries: 10,
            default_ttl_ms: 100,
            ..Default::default()
        });

        cache.put("x", "temp", Some(50), None);
        tokio::time::sleep(Duration::from_millis(80)).await;

        assert_eq!(cache.get("x"), None);
    }

    #[test]
    fn test_access_order() {
        let cache = LRUCache::new(CacheConfig {
            max_entries: 3,
            default_ttl_ms: 1000,
            ..Default::default()
        });

        cache.put("1", "one", None, None);
        cache.put("2", "two", None, None);
        cache.put("3", "three", None, None);
        cache.get("1"); // access '1', making '2' the LRU
        cache.put("4", "four", None, None); // should evict '2'

        assert!(!cache.has("2"));
        assert!(cache.has("1"));
    }

    #[test]
    fn test_stats() {
        let cache = LRUCache::new(CacheConfig {
            max_entries: 10,
            default_ttl_ms: 100,
            ..Default::default()
        });

        cache.put("a", "hello", None, None);
        cache.get("a");
        cache.get("b"); // miss

        let stats = cache.get_stats();
        assert!(stats.hits > 0);
        assert!(stats.misses > 0);
    }

    #[tokio::test]
    async fn test_eviction_loop() {
        let cache = LRUCache::new(CacheConfig {
            max_entries: 10,
            default_ttl_ms: 50,
            eviction_check_interval_ms: 30,
            ..Default::default()
        });

        cache.put("e1", "val1", None, None);
        cache.start_eviction_loop().await;

        tokio::time::sleep(Duration::from_millis(150)).await;

        assert!(!cache.has("e1"));

        cache.stop_eviction_loop().await;
    }

    #[test]
    fn test_clear() {
        let cache = LRUCache::new(CacheConfig {
            max_entries: 10,
            default_ttl_ms: 1000,
            ..Default::default()
        });

        cache.put("a", "hello", None, None);
        cache.put("b", "world", None, None);
        cache.clear();

        assert_eq!(cache.size(), 0);
    }

    #[test]
    fn test_keys_values() {
        let cache = LRUCache::new(CacheConfig {
            max_entries: 10,
            default_ttl_ms: 1000,
            ..Default::default()
        });

        cache.put("a", "hello", None, None);
        cache.put("b", "world", None, None);

        let keys = cache.keys();
        assert_eq!(keys.len(), 2);

        let values = cache.values();
        assert_eq!(values.len(), 2);
    }

    #[test]
    fn test_memory_limit() {
        let cache = LRUCache::new(CacheConfig {
            max_entries: 100,
            default_ttl_ms: 1000,
            max_memory_bytes: 100,
            ..Default::default()
        });

        // Put items and hit memory limit
        cache.put("a", "hello", None, Some(60));
        cache.put("b", "world", None, Some(60));

        // Should have evicted 'a' to make room
        assert!(cache.has("b"));
    }

    #[test]
    fn test_on_evict_callback() {
        let evict_count = Arc::new(AtomicUsize::new(0));
        let evict_count_clone = Arc::clone(&evict_count);

        let on_evict: OnEvictFn = Arc::new(move |_key: String, _reason: String| {
            evict_count_clone.fetch_add(1, Ordering::SeqCst);
        });

        let cache = LRUCache::new(CacheConfig {
            max_entries: 2,
            default_ttl_ms: 1000,
            on_evict: Some(on_evict),
            ..Default::default()
        });

        cache.put("a", "hello", None, None);
        cache.put("b", "world", None, None);
        cache.put("c", "foo", None, None); // should trigger eviction

        assert!(evict_count.load(Ordering::SeqCst) > 0);
    }

    #[test]
    fn test_delete_method() {
        let cache = LRUCache::new(CacheConfig {
            max_entries: 10,
            default_ttl_ms: 1000,
            ..Default::default()
        });

        cache.put("a", "hello", None, None);
        assert!(cache.delete("a", "lru"));
        assert!(!cache.has("a"));
        assert!(!cache.delete("a", "lru")); // second delete returns false
    }
}
